CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('admin','team','customer')),active INTEGER NOT NULL DEFAULT 1, insertion_order BIGINT GENERATED BY DEFAULT AS IDENTITY);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires BIGINT NOT NULL, insertion_order BIGINT GENERATED BY DEFAULT AS IDENTITY);
CREATE TABLE IF NOT EXISTS attempts(email TEXT PRIMARY KEY,count INTEGER NOT NULL,until_at BIGINT NOT NULL, insertion_order BIGINT GENERATED BY DEFAULT AS IDENTITY);
CREATE TABLE IF NOT EXISTS enquiries(id TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES users(id),assigned_to TEXT REFERENCES users(id),destination TEXT NOT NULL,requirements TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'New',followup TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL, insertion_order BIGINT GENERATED BY DEFAULT AS IDENTITY);
CREATE TABLE IF NOT EXISTS activity(id TEXT PRIMARY KEY,actor_id TEXT NOT NULL REFERENCES users(id),message TEXT NOT NULL,created_at TEXT NOT NULL, insertion_order BIGINT GENERATED BY DEFAULT AS IDENTITY);
CREATE TABLE IF NOT EXISTS customer_profiles(user_id TEXT PRIMARY KEY REFERENCES users(id),phone TEXT NOT NULL DEFAULT '',city TEXT NOT NULL DEFAULT '',address TEXT NOT NULL DEFAULT '',preferences TEXT NOT NULL DEFAULT '',updated_at TEXT NOT NULL, insertion_order BIGINT GENERATED BY DEFAULT AS IDENTITY);
CREATE TABLE IF NOT EXISTS admin_leads(id TEXT PRIMARY KEY,payload TEXT NOT NULL,submission_key TEXT UNIQUE, insertion_order BIGINT GENERATED BY DEFAULT AS IDENTITY);
CREATE TABLE IF NOT EXISTS travel_bookings(id TEXT PRIMARY KEY,quote_id TEXT NOT NULL DEFAULT '',payload TEXT NOT NULL, insertion_order BIGINT GENERATED BY DEFAULT AS IDENTITY);
CREATE TABLE IF NOT EXISTS booking_payments(id TEXT PRIMARY KEY,booking_id TEXT NOT NULL REFERENCES travel_bookings(id),payload TEXT NOT NULL, insertion_order BIGINT GENERATED BY DEFAULT AS IDENTITY);
CREATE TABLE IF NOT EXISTS website_booking_requests(request_key TEXT PRIMARY KEY,booking_id TEXT NOT NULL REFERENCES travel_bookings(id), insertion_order BIGINT GENERATED BY DEFAULT AS IDENTITY);
CREATE TABLE IF NOT EXISTS website_content(id INTEGER PRIMARY KEY CHECK(id=1),revision INTEGER NOT NULL,payload TEXT NOT NULL,updated_at TEXT NOT NULL, insertion_order BIGINT GENERATED BY DEFAULT AS IDENTITY);
CREATE TABLE IF NOT EXISTS website_reviews(id TEXT PRIMARY KEY,name TEXT NOT NULL,destination TEXT NOT NULL,rating INTEGER NOT NULL,body TEXT NOT NULL,published INTEGER NOT NULL DEFAULT 0,permission INTEGER NOT NULL,created_at TEXT NOT NULL, insertion_order BIGINT GENERATED BY DEFAULT AS IDENTITY);
CREATE TABLE IF NOT EXISTS travel_feature_migrations(version INTEGER PRIMARY KEY,applied_at TEXT NOT NULL, insertion_order BIGINT GENERATED BY DEFAULT AS IDENTITY);
CREATE TABLE IF NOT EXISTS trip_plans(booking_id TEXT PRIMARY KEY REFERENCES travel_bookings(id),revision INTEGER NOT NULL DEFAULT 0,coordinator TEXT NOT NULL DEFAULT '{}',draft TEXT NOT NULL DEFAULT '[]',published TEXT NOT NULL DEFAULT '[]',published_at TEXT, insertion_order BIGINT GENERATED BY DEFAULT AS IDENTITY);
CREATE TABLE IF NOT EXISTS trip_services(id TEXT PRIMARY KEY,booking_id TEXT NOT NULL REFERENCES trip_plans(booking_id),kind TEXT NOT NULL CHECK(kind IN ('transport','hotel','taxi','food','sightseeing')),status TEXT NOT NULL CHECK(status IN ('Pending','Confirmed','Changed','Cancelled')),fields TEXT NOT NULL,updated_at TEXT NOT NULL, insertion_order BIGINT GENERATED BY DEFAULT AS IDENTITY);
CREATE TABLE IF NOT EXISTS trip_documents(id TEXT PRIMARY KEY,service_id TEXT NOT NULL REFERENCES trip_services(id) ON DELETE CASCADE,name TEXT NOT NULL,mime TEXT NOT NULL,size INTEGER NOT NULL,content BYTEA NOT NULL, insertion_order BIGINT GENERATED BY DEFAULT AS IDENTITY);
CREATE TABLE IF NOT EXISTS trip_notifications(id TEXT PRIMARY KEY,booking_id TEXT NOT NULL REFERENCES trip_plans(booking_id),message TEXT NOT NULL,created_at TEXT NOT NULL,is_read INTEGER NOT NULL DEFAULT 0, insertion_order BIGINT GENERATED BY DEFAULT AS IDENTITY);
CREATE UNIQUE INDEX IF NOT EXISTS booking_quote_unique ON travel_bookings(quote_id) WHERE quote_id!='';
CREATE INDEX IF NOT EXISTS trip_service_booking ON trip_services(booking_id);
CREATE INDEX IF NOT EXISTS trip_notification_booking ON trip_notifications(booking_id);
